class TestSummarize:
    def test_counts_each_kind(self):
        reports = [
            "created skills/a",
            "updated skills/b",
            "removed skills/c (source no longer exists)",
            "up to date skills/d",
            "skipped skills/e: exists and is not a symlink, leaving alone",
        ]

        assert sync_symlinks.summarize(reports) == "1 created, 1 updated, 1 removed, 2 skipped/up to date"
